let opportunities=[];
let researchResults=[];
const profileTopics=["artificial intelligence","cybersecurity","payment","financial technology","distributed systems","stem education","cloud"];
const claims=[
 {claim:"Third-party side effects escape the agent's local transaction boundary.",strength:"Primary + incidents",state:"Supported",action:"Connect failure taxonomy"},
 {claim:"Durable receipts reduce ambiguity during reconciliation.",strength:"Standards + prototypes",state:"Mixed",action:"Define receipt semantics"},
 {claim:"A responsibility protocol improves recovery ownership.",strength:"Design hypothesis",state:"Open",action:"Run expert interviews"}
];
const skills=[
 {name:"Systems research",level:72,note:"Strong synthesis"},{name:"Experimental design",level:44,note:"Needs practice"},{name:"Technical writing",level:78,note:"Publication ready"},{name:"Peer review",level:64,note:"Build consistency"},{name:"Public speaking",level:58,note:"Refine narrative"},{name:"Community mentoring",level:82,note:"Core strength"}
];
const projects=[
 {name:"Payment Safety Curriculum",owner:"Community colleges",need:"Review a lab on idempotency and recovery",impact:"240 students",points:35,tags:["Education","Payments"]},
 {name:"Open Incident Dataset",owner:"SRE Research Circle",need:"Anonymize and classify 20 failure cases",impact:"Public dataset",points:50,tags:["Research","Open data"]},
 {name:"Student Innovation Clinic",owner:"Engineering mentors",need:"Guide one team through problem validation",impact:"8 student teams",points:30,tags:["Mentoring","AI"]}
];
const evidence=[
 {date:"Sep 2026",title:"Transaction Boundary Failure Model",detail:"Research framework with three technical diagrams",type:"Original contribution"},
 {date:"Aug 2026",title:"mcp-gate open-source release",detail:"Ephemeral capability-token proxy implemented in Go",type:"Open-source artifact"},
 {date:"Jul 2026",title:"Payment reliability mentoring session",detail:"Architecture review for an engineering student cohort",type:"Community service"},
 {date:"May 2026",title:"BFCM resilience program",detail:"Production readiness and operational evidence",type:"Leading role"}
];
const savedOpportunityKeys=(()=>{try{return new Set(JSON.parse(localStorage.getItem("savedOpportunities")||"[]"))}catch{return new Set()}})();
const state={view:"overview",filter:"All",search:"",saved:savedOpportunityKeys,impact:Number(localStorage.getItem("impactPoints")||340),skillHours:Number(localStorage.getItem("skillHours")||24),tasks:JSON.parse(localStorage.getItem("impactTasks")||"{}")};
const titles={overview:["Overview","Your impact workspace"],opportunities:["Opportunities","Find work that matters"],proposal:["Proposal Studio","Shape a credible proposal"],research:["Research Studio","Challenge the idea before publishing"],skills:["Skill Lab","Build capability through practice"],community:["Community","Contribute to shared progress"],evidence:["Evidence Vault","Document authentic impact"]};
const typeClass=t=>t.toLowerCase().replaceAll(" ","-");
const escapeHtml=value=>String(value??"").replace(/[&<>"']/g,char=>({"&":"&amp;","<":"&lt;",">":"&gt;","\"":"&quot;","'":"&#039;"}[char]));
function showToast(message){const el=document.querySelector("#toast");el.textContent=message;el.classList.add("show");clearTimeout(showToast.timer);showToast.timer=setTimeout(()=>el.classList.remove("show"),2400)}
function navigate(view){state.view=view;document.querySelectorAll(".view").forEach(v=>v.classList.toggle("active",v.id===`view-${view}`));document.querySelectorAll(".nav-item").forEach(n=>n.classList.toggle("active",n.dataset.view===view));document.querySelector("#crumb").textContent=titles[view][0];document.querySelector("#page-title").textContent=titles[view][1];document.querySelector(".sidebar").classList.remove("open");document.querySelector("#mobile-menu").setAttribute("aria-expanded","false");window.scrollTo({top:0,behavior:"smooth"})}
function relevanceFor(record){const text=`${record.title} ${record.org} ${(record.tags||[]).join(" ")}`.toLowerCase();const matches=profileTopics.filter(topic=>text.includes(topic)).length;return Math.min(97,62+(matches*8)+(record.source?.authoritative?5:0))}
function formatRetrieved(value){if(!value)return "Retrieval time unavailable";const date=new Date(value);return Number.isNaN(date.valueOf())?value:`Retrieved ${date.toLocaleDateString(undefined,{month:"short",day:"numeric",year:"numeric"})}`}
function opportunityKey(o){return `${o.source?.name||"source"}:${o.sourceRecordId||o.applicationUrl||o.title}`}
function isSaved(o){return state.saved.has(opportunityKey(o))}
function persistSaved(){localStorage.setItem("savedOpportunities",JSON.stringify([...state.saved]))}
function updateShortlistSummary(){const count=opportunities.filter(isSaved).length;document.querySelector("#saved-count").textContent=count;document.querySelector("#saved-filter-count").textContent=count;document.querySelector("#saved-summary").textContent=count?`${count} verified ${count===1?"opportunity is":"opportunities are"} ready to review and export.`:"Save official opportunities to build a focused shortlist on this device.";document.querySelector("#export-shortlist").disabled=count===0}
function compactCard(o){return `<article class="op-card"><span class="op-type ${typeClass(o.type)}">${escapeHtml(o.icon)}</span><div class="op-main"><strong>${escapeHtml(o.title)}</strong><small>${escapeHtml(o.type)} · ${escapeHtml(o.org)}</small></div><div class="op-meta"><span class="match">${o.match}% relevance</span><span class="deadline">Due ${escapeHtml(o.deadline)}</span></div></article>`}
function fullCard(o){const saved=isSaved(o);return `<article class="op-card${saved?" saved":""}"><div class="op-card-head"><span class="op-type ${typeClass(o.type)}">${escapeHtml(o.icon)}</span><span class="match">${o.match}% relevance</span></div><div><span class="eyebrow">${escapeHtml(o.type)} · ${escapeHtml(o.org)}</span><h3>${escapeHtml(o.title)}</h3><p>${escapeHtml(o.why)}</p></div><div class="tag-row">${o.tags.map(t=>`<span>${escapeHtml(t)}</span>`).join("")}</div><div class="source-line">${escapeHtml(o.source.name)} · ${escapeHtml(formatRetrieved(o.source.retrievedAt))}</div><div class="op-card-actions"><a class="button secondary source-link" href="${escapeHtml(o.applicationUrl||o.source.url)}" target="_blank" rel="noopener noreferrer">Official application ↗</a><button class="button secondary save-opportunity${saved?" saved":""}" data-key="${escapeHtml(opportunityKey(o))}" aria-pressed="${saved}">${saved?"★ Saved":"☆ Save"}</button><button class="button primary draft" data-id="${o.id}">Draft pitch</button></div></article>`}
function renderOpportunities(){const overview=document.querySelector("#overview-opportunities");overview.innerHTML=opportunities.length?opportunities.slice(0,3).map(compactCard).join(""):`<div class="loading-card">Loading verified opportunities…</div>`;const q=state.search.toLowerCase();const list=opportunities.filter(o=>{const filterMatches=state.filter==="All"||(state.filter==="Saved"?isSaved(o):o.type===state.filter);return filterMatches&&(`${o.title} ${o.org} ${o.tags.join(" ")}`.toLowerCase().includes(q))});document.querySelector("#opportunity-grid").innerHTML=list.length?list.map(fullCard).join(""):`<div class="panel"><h3>No verified records found</h3><p>${state.filter==="Saved"?"Save an opportunity from the verified source list to add it here.":"Try another topic or category. Categories without an official connector remain empty rather than showing synthetic data."}</p></div>`;updateShortlistSummary()}
function exportShortlist(){const saved=opportunities.filter(isSaved);if(!saved.length)return showToast("Save an opportunity before exporting");const generated=new Date().toLocaleDateString(undefined,{year:"numeric",month:"long",day:"numeric"});const text=["# Impact Commons opportunity shortlist","",`Generated ${generated}. Verify details on each official source before applying.`,"",...saved.flatMap((o,index)=>[`## ${index+1}. ${o.title}`,"",`- Type: ${o.type}`,`- Organization: ${o.org}`,`- Deadline: ${o.deadline||"Not published"}`,`- Official source: ${o.source.name}`,`- Application: ${o.applicationUrl||o.source.url}`,""])] .join("\n");const blob=new Blob([text],{type:"text/markdown"});const a=document.createElement("a");a.href=URL.createObjectURL(blob);a.download="impact-commons-shortlist.md";a.click();URL.revokeObjectURL(a.href);showToast("Verified opportunity shortlist exported")}
async function loadOpportunities(){const status=document.querySelector("#opportunity-source-status");try{status.classList.remove("error");status.querySelector("strong").textContent="Loading verified sources";status.querySelector("small").textContent="Reading the latest normalized official-source cache.";const payload=await window.AuthenticData.loadCachedOpportunities();opportunities=payload.records.map((record,index)=>({...record,id:index+1,match:relevanceFor(record)}));const counts=payload.counts||{};const sourceNames=Object.keys(counts);document.querySelector("#matched-count").textContent=opportunities.length;document.querySelector("#opportunity-count").textContent=opportunities.length;document.querySelector("#opportunity-freshness").textContent=formatRetrieved(payload.generatedAt);document.querySelector("#coverage-funding").textContent=`${counts["Grants.gov"]||0} live`;document.querySelector("#coverage-challenge").textContent=`${counts["USA.gov"]||0} live`;document.querySelector("#coverage-speaking").textContent=`${counts.Sessionize||0} live`;status.querySelector("strong").textContent=`Verified across ${sourceNames.length} authentic sources`;status.querySelector("small").textContent=`${opportunities.length} official records · ${formatRetrieved(payload.generatedAt)} · refreshed daily`;renderOpportunities()}catch(error){status.classList.add("error");status.querySelector("strong").textContent="Official source unavailable";status.querySelector("small").textContent=error.message;document.querySelector("#opportunity-grid").innerHTML=`<div class="panel"><h3>We could not verify opportunities</h3><p>No cached or invented results are being shown. Try refreshing later.</p></div>`}}
function renderClaims(){document.querySelector("#claims-body").innerHTML=claims.map(c=>`<tr><td>${c.claim}</td><td>${c.strength}</td><td><span class="status-chip ${c.state.toLowerCase()}">${c.state}</span></td><td>${c.action}</td></tr>`).join("")}
function renderSkills(){document.querySelector("#skill-nodes").innerHTML=skills.map(s=>`<article class="skill-node"><strong>${s.name}</strong><small>${s.note}</small><div class="skill-progress"><i style="width:${s.level}%"></i></div></article>`).join("")}
function renderProjects(){document.querySelector("#community-grid").innerHTML=projects.map((p,i)=>`<article class="project-card"><div class="project-top"><span class="eyebrow">${p.owner}</span><span class="match">+${p.points} impact</span></div><h3>${p.name}</h3><div class="tag-row">${p.tags.map(t=>`<span>${t}</span>`).join("")}</div><div class="needs"><small>Current need</small><strong>${p.need}</strong></div><p>Potential reach: ${p.impact}</p><footer><div class="contributors"><span>AR</span><span>SK</span><span>+3</span></div><button class="button primary contribute" data-points="${p.points}" data-project="${i}">Contribute</button></footer></article>`).join("")}
function renderEvidence(){document.querySelector("#evidence-timeline").innerHTML=evidence.map(e=>`<article class="timeline-item"><small>${e.date} · ${e.type}</small><strong>${e.title}</strong><p>${e.detail}</p></article>`).join("")}
function renderResearchResults(records,errors=[]){const target=document.querySelector("#research-results");const cards=records.map((record,index)=>`<article class="research-result"><div class="source-line">${escapeHtml(record.source.name)} · ${escapeHtml(record.year||"Year unavailable")}</div><h4><a class="source-link" href="${escapeHtml(record.url)}" target="_blank" rel="noopener noreferrer">${escapeHtml(record.title)}</a></h4><p>${record.authors.length?record.authors.map(escapeHtml).join(", "):"Authors unavailable"}${record.venue?` · ${escapeHtml(record.venue)}`:""}</p><footer><span>${record.citations.toLocaleString()} citations${record.doi?` · DOI ${escapeHtml(record.doi)}`:""}</span><button class="button secondary add-research" data-index="${index}">Add to ledger</button></footer></article>`).join("");const failures=errors.map(error=>`<div class="source-error"><strong>${escapeHtml(error.source)}</strong>: ${escapeHtml(error.message)}</div>`).join("");target.innerHTML=(cards||`<div class="loading-card">No records matched this research question.</div>`)+failures}
async function searchResearch(query){const status=document.querySelector("#research-source-status");const target=document.querySelector("#research-results");status.textContent="Querying Crossref and OpenAlex, plus the verified OpenReview cache…";target.innerHTML=`<div class="loading-card">Retrieving and deduplicating scholarly metadata…</div>`;try{const result=await window.AuthenticData.searchResearch(query);researchResults=result.records;renderResearchResults(result.records,result.errors);status.textContent=`${result.records.length} deduplicated records · ${formatRetrieved(result.retrievedAt)}${result.errors.length?` · ${result.errors.length} source warning(s)`:""}`}catch(error){researchResults=[];target.innerHTML=`<div class="source-error">Research sources are currently unavailable: ${escapeHtml(error.message)}</div>`;status.textContent="No unverified fallback results are shown."}}
function updateMetrics(){document.querySelector("#impact-points").textContent=state.impact;document.querySelector("#skill-hours").textContent=state.skillHours;localStorage.setItem("impactPoints",state.impact);localStorage.setItem("skillHours",state.skillHours)}
document.addEventListener("click",e=>{const nav=e.target.closest("[data-view]");if(nav)navigate(nav.dataset.view);const go=e.target.closest("[data-go]");if(go)navigate(go.dataset.go);const filter=e.target.closest(".filter");if(filter){state.filter=filter.dataset.filter;document.querySelectorAll(".filter").forEach(f=>f.classList.toggle("active",f===filter));renderOpportunities()}const save=e.target.closest(".save-opportunity");if(save){const key=save.dataset.key;if(state.saved.has(key)){state.saved.delete(key);showToast("Removed from your shortlist")}else{state.saved.add(key);showToast("Saved to your shortlist")}persistSaved();renderOpportunities()}const detail=e.target.closest(".detail");if(detail){const o=opportunities.find(x=>x.id===Number(detail.dataset.id));document.querySelector("#dialog-content").innerHTML=`<span class="eyebrow">${o.type} · ${o.org}</span><h2>${o.title}</h2><p>${o.why}</p><div class="dialog-detail-grid"><div><small>Match</small><strong>${o.match}%</strong></div><div><small>Deadline</small><strong>${o.deadline}</strong></div><div><small>Estimated effort</small><strong>${o.effort}</strong></div><div><small>Evidence created</small><strong>${o.proof}</strong></div></div><div class="tag-row">${o.tags.map(t=>`<span>${t}</span>`).join("")}</div>`;document.querySelector("#detail-dialog").showModal()}const draft=e.target.closest(".draft");if(draft){const o=opportunities.find(x=>x.id===Number(draft.dataset.id));document.querySelector("#proposal-event").innerHTML=`<option>${o.title} — ${o.type}</option>`;document.querySelector("#proposal-title").value=o.type==="Speaking"?"The Transaction Boundary AI Agents Cannot See":`A systems perspective for ${o.title}`;navigate("proposal");showToast("Opportunity brief loaded into Proposal Studio")}const contribution=e.target.closest(".contribute");if(contribution&&!contribution.disabled){contribution.disabled=true;contribution.textContent="Joined";state.impact+=Number(contribution.dataset.points||20);updateMetrics();showToast("Contribution added to your queue")}});
document.querySelector("#mobile-menu").addEventListener("click",e=>{const open=document.querySelector(".sidebar").classList.toggle("open");e.currentTarget.setAttribute("aria-expanded",String(open))});
document.querySelector("#opportunity-search").addEventListener("input",e=>{state.search=e.target.value;renderOpportunities()});
document.querySelector("#refresh-opportunities").addEventListener("click",loadOpportunities);
document.querySelector("#export-shortlist").addEventListener("click",exportShortlist);
document.querySelector("#research-search-form").addEventListener("submit",event=>{event.preventDefault();const query=document.querySelector("#research-search").value.trim();if(!query)return showToast("Enter a research question or topic");searchResearch(query)});
document.addEventListener("click",event=>{const button=event.target.closest(".add-research");if(!button)return;const record=researchResults[Number(button.dataset.index)];if(!record)return;claims.push({claim:`Evidence candidate: ${record.title}`,strength:`${record.source.name}${record.doi?" + DOI":""}`,state:"Open",action:"Read and assess relevance"});renderClaims();button.disabled=true;button.textContent="Added";showToast("Scholarly record added to the evidence ledger")});
document.querySelector("#proposal-form").addEventListener("submit",e=>{e.preventDefault();const title=document.querySelector("#proposal-title").value.trim();const idea=document.querySelector("#proposal-idea").value.trim();const ev=document.querySelector("#proposal-evidence").value.trim();const audience=document.querySelector("#proposal-audience").value;const tone=document.querySelector("#proposal-tone").value;const format=document.querySelector("#proposal-format").value;const output=`${title}\n\nModern AI agents can initiate increasingly consequential actions, yet the systems around them still struggle to prove what happened across an unreliable external boundary. This ${format.toLowerCase()} presents a practical model for ${idea.charAt(0).toLowerCase()+idea.slice(1)}\n\nDrawing on ${ev.charAt(0).toLowerCase()+ev.slice(1)}, the session separates four responsibilities that are often collapsed: intent, authorization, side-effect confirmation, and reconciliation. Participants will examine where ordinary retries and local transaction guarantees stop working, then use a durable-receipt pattern to assign recovery ownership without assuming third-party idempotency.\n\nDesigned for ${audience.toLowerCase()}, the result is a concrete checklist, a failure-mode map, and a small evaluation framework teams can adapt to their own agentic workflows. The treatment will be ${tone.toLowerCase()}, with claims tied to inspectable evidence and open limitations.`;document.querySelector("#proposal-output").value=output;document.querySelector("#quality-score").textContent="91";document.querySelectorAll("#quality-checks span").forEach(x=>{x.classList.add("pass");x.textContent="✓ "+x.textContent.slice(2)});localStorage.setItem("proposalDraft",output);showToast("Evidence-led draft generated")});
document.querySelector("#proposal-output").value=localStorage.getItem("proposalDraft")||"";
document.querySelector("#copy-proposal").addEventListener("click",async()=>{const t=document.querySelector("#proposal-output").value;if(!t)return showToast("Generate a draft first");await navigator.clipboard.writeText(t);showToast("Draft copied")});
document.querySelector("#save-evidence").addEventListener("click",()=>{if(!document.querySelector("#proposal-output").value)return showToast("Generate a draft first");evidence.unshift({date:"Today",title:document.querySelector("#proposal-title").value,detail:"AI-assisted draft grounded in verified professional evidence",type:"Working artifact"});renderEvidence();showToast("Draft added to evidence vault")});
document.querySelector("#analyze-gap").addEventListener("click",()=>{document.querySelector("#gap-output").className="gap-result";document.querySelector("#gap-output").innerHTML=`<article><strong>Unresolved ownership</strong><p>The model identifies receipts but must name who reconciles when the provider exposes no idempotency key.</p></article><article><strong>Testable novelty</strong><p>Compare receipt-based recovery against retry-only and human-queue baselines using injected boundary failures.</p></article><article><strong>Community value</strong><p>Publish a reusable incident taxonomy and reference implementation so independent teams can reproduce the result.</p></article>`;showToast("Three research gaps surfaced")});
document.querySelector("#add-claim").addEventListener("click",()=>{claims.push({claim:"New claim — replace with a precise, falsifiable statement.",strength:"Not assessed",state:"Open",action:"Find primary evidence"});renderClaims();showToast("Claim added to the ledger")});
document.querySelector("#create-sprint").addEventListener("click",()=>{document.querySelector("#sprint-title").textContent="Experimental design for systems research";document.querySelector("#sprint-tasks").innerHTML=["Frame one falsifiable hypothesis","Define retry-only and receipt-based baselines","Inject three third-party failure modes","Publish results and ask two peers to reproduce"].map((t,i)=>`<div class="sprint-task"><b>${i+1}</b><span><strong>${t}</strong><small>${["20 min","40 min","90 min","60 min"][i]}</small></span></div>`).join("");state.skillHours+=4;updateMetrics();showToast("Applied sprint created")});
document.querySelectorAll("[data-task]").forEach(input=>{input.checked=Boolean(state.tasks[input.dataset.task]);input.addEventListener("change",()=>{state.tasks[input.dataset.task]=input.checked;localStorage.setItem("impactTasks",JSON.stringify(state.tasks));if(input.checked){state.impact+=10;updateMetrics();showToast("Task completed · +10 impact")}})});
document.querySelector(".dialog-close").addEventListener("click",()=>document.querySelector("#detail-dialog").close());
document.querySelector("#detail-dialog").addEventListener("click",e=>{if(e.target===e.currentTarget)e.currentTarget.close()});
document.querySelector("#add-evidence").addEventListener("click",()=>{evidence.unshift({date:"Today",title:"New contribution",detail:"Add source, reviewer, and measurable outcome before using this evidence.",type:"Unverified"});renderEvidence();showToast("Evidence placeholder added")});
document.querySelector("#export-evidence").addEventListener("click",()=>{const text=["IMPACT COMMONS — EVIDENCE SUMMARY","",...evidence.map(e=>`${e.date} | ${e.type}\n${e.title}\n${e.detail}\n`)].join("\n");const blob=new Blob([text],{type:"text/plain"});const a=document.createElement("a");a.href=URL.createObjectURL(blob);a.download="impact-evidence-summary.txt";a.click();URL.revokeObjectURL(a.href);showToast("Evidence summary exported")});
document.querySelector("#reset-demo").addEventListener("click",()=>{localStorage.clear();location.reload()});
renderOpportunities();renderClaims();renderSkills();renderProjects();renderEvidence();updateMetrics();loadOpportunities();
